import{_ as a,C as n,c as r,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Project settings","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/project/get-started/project-settings.md","filePath":"master/services/project/get-started/project-settings.md","lastUpdated":1792041590000}'),l={name:"master/services/project/get-started/project-settings.md"};function g(c,e,h,m,p,d){const s=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="project-settings" tabindex="-1">Project settings <a class="header-anchor" href="#project-settings" aria-label="Permalink to &quot;Project settings&quot;">​</a></h1><p>Project settings switch optional features on or off for your whole company. A feature you switch off is hidden from forms and menus. This keeps screens short for teams that do not need milestones or time tracking.</p><blockquote><p><strong>In simple words:</strong> Three switches decide which fields and pages you see in Project.</p></blockquote><p>There are two settings pages. Open <code>Project → Settings → Manage Tasks</code> and <code>Project → Settings → Manage Time</code>. Both have a <strong>Save changes</strong> button. Click it after every change.</p><div class="info custom-block"><p class="custom-block-title">Who can see these pages</p><p>You need permission to open Settings. Ask an administrator if the menu is missing. See <a href="./../../../general-settings/users/manage-users.html">Manage users</a>.</p></div><h2 id="manage-tasks" tabindex="-1">Manage Tasks <a class="header-anchor" href="#manage-tasks" aria-label="Permalink to &quot;Manage Tasks&quot;">​</a></h2><ol><li>Open <code>Project → Settings → Manage Tasks</code>.</li><li>Switch the toggles you need.</li><li>Click <strong>Save changes</strong>.</li></ol>',7)),o(s,{src:"/images1/project/st_manage_tasks.png",alt:"Manage Tasks settings page with Enable Project Stages and Enable Milestones toggles and the Save changes button"}),e[1]||(e[1]=t('<ul><li><strong><em>Enable Project Stages:</em></strong> Shows the stage bar on the project form. Pick a stage such as <strong>In Progress</strong> for each project. The stage list lives in <code>Project → Configurations → Project Stages</code>. Off by default.</li><li><strong><em>Enable Milestones:</em></strong> Adds the <strong>Allow Milestones</strong> toggle to projects. It also adds the <strong>Milestones</strong> page and the <strong>Milestone</strong> field on tasks. On by default.</li></ul><p>The page also shows a <strong>Configure Stages</strong> link next to <strong>Enable Project Stages</strong>.</p><h2 id="manage-time" tabindex="-1">Manage Time <a class="header-anchor" href="#manage-time" aria-label="Permalink to &quot;Manage Time&quot;">​</a></h2><ol><li>Open <code>Project → Settings → Manage Time</code>.</li><li>Switch on <strong>Enable Timesheets</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol>',4)),o(s,{src:"/images1/project/st_manage_time.png",alt:"Manage Time settings page with Enable Timesheets switched on and the Save changes button"}),e[2]||(e[2]=t('<ul><li><strong><em>Enable Timesheets:</em></strong> Lets people log hours on tasks. Off by default.</li></ul><p>When <strong>Enable Timesheets</strong> is on, these appear:</p><ul><li><strong>Allow Timesheets</strong> on each project.</li><li><strong>Allocated Hours</strong> on projects and tasks.</li><li>A <strong>Timesheets</strong> tab on tasks.</li><li>Time columns and filters on the task list.</li><li>The <strong>Timesheets</strong> item in the Project menu.</li></ul><h2 id="per-project-switches" tabindex="-1">Per project switches <a class="header-anchor" href="#per-project-switches" aria-label="Permalink to &quot;Per project switches&quot;">​</a></h2><p>The settings above are company wide. Each project then chooses for itself.</p><ul><li><strong><em>Allow Timesheets:</em></strong> Shown only when <strong>Enable Timesheets</strong> is on. Without it the project has no <strong>Timesheets</strong> tab on its tasks.</li><li><strong><em>Allow Milestones:</em></strong> Shown only when <strong>Enable Milestones</strong> is on. Without it the project has no milestones and its tasks have no <strong>Milestone</strong> field.</li></ul><p>You set both on the project form. See <a href="./../project-management/create-project.html">Create a project</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For the example in this guide, <strong>Enable Timesheets</strong> and <strong>Enable Milestones</strong> are on. <strong>Website Revamp</strong> has both <strong>Allow Timesheets</strong> and <strong>Allow Milestones</strong> on.</p></div><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Save changes:</strong> stores the toggles. Forms show the new fields at once.</li><li>Switching a feature off hides its fields and pages.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Get started</a></li><li><a href="./../project-management/create-project.html">Create a project</a></li><li><a href="./../../timesheets/timesheet-settings.html">Timesheet settings</a></li><li><a href="./../">Project overview</a></li></ul>',12))])}const T=a(l,[["render",g]]);export{f as __pageData,T as default};
